'use strict';

// MODULES //

var tape = require( 'tape' );
var PINF = require( '@stdlib/constants-float64-pinf' );
var NINF = require( '@stdlib/constants-float64-ninf' );
var MAX_FLOAT64 = require( '@stdlib/constants-float64-max' );
var SMALLEST_SUBNORMAL = require( '@stdlib/constants-float64-smallest-subnormal' );
var isfinite = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof isfinite, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `true` if provided a finite number', function test( t ) {
	var values;
	var i;

	values = [
		3.14,
		-2.0e64,
		MAX_FLOAT64,
		SMALLEST_SUBNORMAL
	];

	for ( i = 0; i < values.length; i++ ) {
		t.strictEqual( isfinite( values[i] ), true, 'returns expected value when provided '+values[i] );
	}
	for ( i = -100; i < 101; i++ ) {
		t.strictEqual( isfinite( i ), true, 'returns expected value when provided '+i );
	}
	t.end();
});

tape( 'the function returns `false` if provided `+infinity`', function test( t ) {
	t.strictEqual( isfinite( PINF ), false, 'returns expected value' );
	t.end();
});

tape( 'the function returns `false` if provided `-infinity`', function test( t ) {
	t.strictEqual( isfinite( NINF ), false, 'returns expected value' );
	t.end();
});

tape( 'the function returns `false` if provided `NaN`', function test( t ) {
	t.strictEqual( isfinite( NaN ), false, 'returns expected value' );
	t.strictEqual( isfinite( 0/0 ), false, 'returns expected value' );
	t.end();
});","lineStart":1,"lineEnd":73,"totalLines":73,"truncated":false}},"title":"repos/pc-lib-3456/math-base-assert-is-finite/test/test.js","time":{"start":1783262126028,"end":1783262126032}},"id":"prt_f32b49f300016foBnTGjW8RrcJ","sessionID":"ses_0cd4bb1f0ffe3rcMHSAimN4lrP","messageID":"msg_f32b49230001dDIDjV1Z6GgQX1"}}

